//! Request consumer: actual semantic adoption can precede source-backed detailed completion.
use super::evidence::*;
use crate::context::Context;use serde_json::{json,Value};
const ANSWER_SCHEMA:&str="answer:{targets:[source ID strings],text:string,facts:[{statement:string,source_id:string,revision:number,start_line:number,end_line:number,quote:string}],source_revisions:[{source_id:string,revision:number}],conditions:[string],uncertainties:[string]}";
fn support(variant:&str,rolling:&[Value],recent:&[Value],published:&Value,sources:&Sources)->Vec<Value>{
 let mut units=Vec::new();if variant=="A"{units.extend(rolling.iter().filter(|p|valid_span(p,sources)).cloned());}
 if variant=="C"{for r in array(&published["records"]){units.extend(array(&r["supporting_passages"]).into_iter().filter(|p|valid_span(p,sources)));}}
 for r in recent{for f in array(&r["facts"]){if valid_span(&f,sources){let mut p=f.clone();p["text"]=r["text"].clone();p["kind"]=json!("ACTUALLY_DELIVERED_ANSWER");p["original_source_provenance"]=json!({"source_id":f["source_id"],"revision":f["revision"],"start_line":f["start_line"],"end_line":f["end_line"]});p.as_object_mut().unwrap().remove("statement");p.as_object_mut().unwrap().remove("quote");units.push(p);}}}units
}
fn adoption(ctx:&Context,event:&Value,proposal:&Value,sources:&Sources,first:bool)->Result<Option<Value>,String>{
 if !targets_valid(&proposal["targets"],sources)||proposal["intent"].as_str().unwrap_or("").trim().is_empty(){return Ok(None);}
 let targets=array(&proposal["targets"]);let titles=targets.iter().filter_map(|t|t.as_str().and_then(|id|sources.get(id)).and_then(|s|s["title"].as_str())).collect::<Vec<_>>().join(", ");
 let versions=targets.iter().filter_map(|t|t.as_str().and_then(|id|sources.get(id)).map(|s|(s["id"].as_str().unwrap().to_owned(),s["revision"].clone()))).collect::<serde_json::Map<String,Value>>();
 let a=json!({"adoption_id":format!("{}-{}",event["expression_id"].as_str().unwrap_or("ref"),if first{"first"}else{"revised"}),"expression_id":event["expression_id"],"revision":event["revision"],"targets":targets,"source_revisions":versions.iter().map(|(id,rev)|json!({"source_id":id,"revision":rev})).collect::<Vec<_>>(),"conditions":[],"first_adoption":first});
 if first{ctx.goal_start(event["goal_id"].as_str().unwrap_or(""),&json!({"stimulus_id":event["stimulus_id"],"raw_utterance":event["utterance"],"revision":event["revision"],"goal_origin":"USER"}));}
 ctx.event("SEMANTIC_ADOPTION",&a);
 ctx.progress(event["goal_id"].as_str().unwrap_or(""),event["stimulus_id"].as_str().unwrap_or(""),&json!({"resolved":true,"adoption_id":a["adoption_id"],"text":format!("{} 자료를 참고하여 {}",titles,proposal["intent"].as_str().unwrap()),"targets":targets,"source_revisions":versions,"scope":event["expression"],"handling":proposal["intent"],"raw_utterance":event["utterance"]}))?;
 Ok(Some(a))
}
pub fn execute(root:&mut Context,event:&Value,variant:&str,sources:&Sources,rolling:&[Value],recent:&[Value],published:&Value)->Result<Value,String>{
 let goal=event["goal_id"].as_str().ok_or("goal_id")?;let stimulus=event["stimulus_id"].as_str().ok_or("stimulus_id")?;
 let mut parents=Vec::new();if variant=="C"{if let Some(n)=published["producer_node"].as_str(){parents.push(n.to_owned());}}
 let mut ctx=root.scoped(&[goal.to_owned()],&parents);ctx.capture(stimulus,&json!({"raw_utterance":event["utterance"],"goal_id":goal,"revision":event["revision"]}));
 let mut available=support(variant,rolling,recent,published,sources);let mut reads=Vec::new();let mut denied=Vec::new();let mut adoptions=Vec::new();
 let initial=ctx.call("dp01_select_adopt_or_complete",&json!({"instruction":format!("Interpret the CURRENT utterance and resolve the exact ORIGINAL source referent IDs, separating supporting explanation from referred targets. Return JSON {{adoption:{{targets:[string],intent:string}},mode:'COMPLETE'|'READ',{},reads:[{{source_id:string,start_line:number,end_line:number}}],reason:string}}. The intent is the concrete requested handling, not a generic acknowledgement. You may adopt identifiable targets before factual details are read. COMPLETE is legal only from actual supplied evidence or actually delivered facts. Metadata alone is NEVER source facts. Supply a bounded substantive answer satisfying the user's actual request, never merely repeat its referent phrase. Each fact claim cites an exact quote from actually supplied evidence, its current revision and inclusive one-based source provenance. The displayed text may paraphrase fact claims. ACTUALLY_DELIVERED_ANSWER is derived previous displayed text, not a verbatim original: quote only its actual text and preserve its separate original source provenance. The quote must be copied exactly (including punctuation) from a supplied evidence.text. Include at least one fact per target and only currently delivered explanation lines. If missing detail, READ necessary bounded ranges. A later fact may need an original read even if recent answers concern that source. Do not invent IDs or values. Preserve unknowns and correction scope.",ANSWER_SCHEMA),"input":{"utterance":event["utterance"],"expression":event["expression"],"catalog":catalog(sources),"recent_conversation":recent,"available_evidence":available,"published_relations":if variant=="C"{published.clone()}else{Value::Null}},"max_tokens":2200}))?;
 ctx.event("EVIDENCE_QUERY",&initial);if let Some(a)=adoption(&ctx,event,&initial["adoption"],sources,true)?{adoptions.push(a);}
 let direct_errors=completion_errors(&initial["answer"],event["utterance"].as_str().unwrap_or(""),event["expression"].as_str().unwrap_or(""),sources,&available);
 let direct=initial["mode"].as_str()==Some("COMPLETE")&&direct_errors.is_empty();
 ctx.event("EVIDENCE_BRANCH",&json!({"branch":if direct{"COMPLETE_FROM_AVAILABLE_EVIDENCE"}else{"BOUNDED_SOURCE_COMPLETION"},"mode":initial["mode"],"completion_errors":direct_errors,"available_source_spans":available}));
 let mut answer=if direct{initial["answer"].clone()}else{
  let mut requests=array(&initial["reads"]);
  // A rejected direct answer with no read plan MUST acquire its missing originals.
  // These are model-selected IDs, never oracle targets or episode-specific facts.
  if requests.is_empty(){let targets=if targets_valid(&initial["adoption"]["targets"],sources){array(&initial["adoption"]["targets"])}else{array(&initial["answer"]["targets"])};
   for t in targets{if let Some(s)=t.as_str().and_then(|id|sources.get(id)){let(a,b)=bounds(s);requests.push(json!({"source_id":t,"start_line":a,"end_line":b}));}}
   ctx.event("MISSING_EVIDENCE_FALLBACK",&json!({"reason":"no_accepted_complete_answer_and_empty_read_plan","requests":requests}));
  }
  if requests.is_empty(){let recovery=ctx.call("dp01_recover_read_selection",&json!({"instruction":"The proposal supplied neither an accepted factual answer nor usable original reads. Select source IDs and bounded ranges needed for this actual utterance. Return JSON {reads:[{source_id:string,start_line:number,end_line:number}],adoption:{targets:[string],intent:string}}. Titles are not facts. Do not return an answer without evidence.","input":{"utterance":event["utterance"],"expression":event["expression"],"catalog":catalog(sources),"previous_proposal":initial},"max_tokens":1000}))?;requests=array(&recovery["reads"]);if adoptions.is_empty(){if let Some(a)=adoption(&ctx,event,&recovery["adoption"],sources,true)?{adoptions.push(a);}}}
  let(p,d)=read_selected(&ctx,&requests,sources,if variant=="A"{rolling}else{&[]});reads.extend(p.clone());denied.extend(d);available.extend(p);
  if available.is_empty(){ctx.fail(goal,&json!({"stimulus_id":stimulus,"reason":"NO_ACTUAL_EVIDENCE_AFTER_BOUNDED_READ","denials":denied}));return Ok(json!({"completed":false,"adoptions":adoptions,"output":{"goal_id":goal,"stimulus_id":stimulus,"text":null,"status":"FAILED_MISSING_EVIDENCE"},"read_passages":reads}));}
  ctx.call("dp01_source_backed_answer",&json!({"instruction":format!("Complete the user's actual requested bounded summary or explanation using ONLY actual supplied current evidence. Return JSON {} (the answer object). Do not echo the user's request or only name source targets. Give actual prices, dates, conditions or unknowns when requested and supported. Each fact claim needs an EXACT copied quote in supplied evidence.text and current source_id/revision/start_line/end_line. Displayed text may paraphrase fact claims. For ACTUALLY_DELIVERED_ANSWER quote only the actual displayed text; preserve original_source_provenance and do not claim the quote is verbatim original text. At least one fact per referred original target. Supporting explanation is not automatically a referred target. Preserve actual delivery limits, scope, caveats and corrections. Do not guess unseen facts. If unable, return text:null and uncertainties.",ANSWER_SCHEMA.trim_start_matches("answer:")),"input":{"utterance":event["utterance"],"expression":event["expression"],"catalog":catalog(sources),"recent_conversation":recent,"actual_evidence":available,"denied":denied},"max_tokens":2200}))?
 };
 let mut errors=completion_errors(&answer,event["utterance"].as_str().unwrap_or(""),event["expression"].as_str().unwrap_or(""),sources,&available);
 if !errors.is_empty(){ctx.event("COMPLETION_REJECTED",&json!({"proposal":answer,"errors":errors}));answer=ctx.call("dp01_repair_source_backed_answer",&json!({"instruction":format!("Repair this rejected bounded answer using ONLY supplied actual evidence. Return JSON {}. Displayed text may paraphrase fact claims; quote must be an EXACT nonempty substring of supplied evidence.text in its current source span. For derived ACTUALLY_DELIVERED_ANSWER evidence quote only actual displayed text with its separate original provenance. Include substantive requested facts for every referred original target. Never echo request as completion; no unseen facts. If material is unavailable return text:null, do not fabricate.",ANSWER_SCHEMA.trim_start_matches("answer:")),"input":{"utterance":event["utterance"],"expression":event["expression"],"proposal":answer,"errors":errors,"actual_evidence":available,"catalog":catalog(sources),"denied":denied},"max_tokens":2200}))?;errors=completion_errors(&answer,event["utterance"].as_str().unwrap_or(""),event["expression"].as_str().unwrap_or(""),sources,&available);}
 if !errors.is_empty(){ctx.fail(goal,&json!({"stimulus_id":stimulus,"reason":"BOUNDED_COMPLETION_CONTRACT_FAILED","errors":errors,"proposal":answer}));return Ok(json!({"completed":false,"adoptions":adoptions,"output":{"goal_id":goal,"stimulus_id":stimulus,"text":null,"status":"FAILED_CONTRACT"},"read_passages":reads}));}
 if adoptions.is_empty()||adoptions.last().map(|a|a["targets"]!=answer["targets"]).unwrap_or(false){if let Some(a)=adoption(&ctx,event,&json!({"targets":answer["targets"],"intent":"요청한 범위의 근거를 정리합니다."}),sources,adoptions.is_empty())?{adoptions.push(a);}}
 let out=json!({"goal_id":goal,"stimulus_id":stimulus,"revision":event["revision"],"text":answer["text"],"details":answer,"raw_utterance":event["utterance"],"content_contract_checked":true,"checks":["current_source_revision","actually_supplied_span_and_exact_quote","separate_actual_display_and_source_claims","non_echo_bounded_answer"],"oracle_semantic_correctness_claimed":false});ctx.complete(goal,&out)?;
 Ok(json!({"completed":true,"adoptions":adoptions,"output":out,"read_passages":reads,"delivered_answer":{"utterance":event["utterance"],"adopted_targets":answer["targets"],"text":answer["text"],"facts":array(&answer["facts"]).iter().map(|f|json!({"source_id":f["source_id"],"revision":f["revision"],"start_line":f["start_line"],"end_line":f["end_line"]})).collect::<Vec<_>>(),"source_revisions":answer["source_revisions"]}}))
}

#[cfg(test)]mod recent_tests{use super::*;
 #[test]fn actual_display_not_unshown_fact_is_reused(){let mut sources=Sources::new();sources.insert("s".into(),json!({"id":"s","revision":1,"line_count":1}));let recent=vec![json!({"text":"Actually displayed paraphrase.","facts":[{"source_id":"s","revision":1,"start_line":1,"end_line":1,"statement":"UNSHOWN statement","quote":"UNSHOWN source quote"}]})];for variant in ["A","B","C"]{let units=support(variant,&[],&recent,&Value::Null,&sources);assert_eq!(units.len(),1);assert_eq!(units[0]["text"],"Actually displayed paraphrase.");assert_eq!(units[0]["kind"],"ACTUALLY_DELIVERED_ANSWER");assert!(!units[0].to_string().contains("UNSHOWN"));assert_eq!(units[0]["original_source_provenance"]["source_id"],"s");assert!(quote_in_span(&units[0],&units[0],"Actually displayed paraphrase."));assert!(!quote_in_span(&units[0],&units[0],"UNSHOWN statement"));}}
}
